const $=s=>document.querySelector(s), app=$('#app');
const users=[['admin@rpsf.local','Admin@123','SUPER_ADMIN','Administrator'],['training@rpsf.local','Training@123','TRAINING_ADMIN','Training Administrator'],['instructor@rpsf.local','Instructor@123','INSTRUCTOR','Inspector R. Singh'],['exam@rpsf.local','Exam@123','EXAM_CELL','Exam Cell Officer'],['trainee@rpsf.local','Rahul@123','TRAINEE','Rahul Kumar']];
const seed={courses:[{id:1,code:'BT-01',name:'Basic Training',duration:'12 weeks',pass:50,status:'ACTIVE'},{id:2,code:'RT-01',name:'Refresher Training',duration:'4 weeks',pass:50,status:'ACTIVE'},{id:3,code:'ST-01',name:'Specialized Training',duration:'8 weeks',pass:55,status:'ACTIVE'}],batches:[{id:1,code:'GKP-BT-2026-01',course:'Basic Training',start:'2026-01-05',end:'2026-03-28',capacity:100,enrolled:28,status:'ACTIVE'},{id:2,code:'GKP-BT-2026-02',course:'Basic Training',start:'2026-04-06',end:'2026-06-28',capacity:100,enrolled:17,status:'ACTIVE'},{id:3,code:'GKP-RT-2026-01',course:'Refresher Training',start:'2026-02-02',end:'2026-03-01',capacity:60,enrolled:14,status:'ACTIVE'}],trainees:[],applications:[],rolls:[],materials:[{title:'Physical Training Manual',subject:'Physical Training',type:'PDF',url:'#'},{title:'Safety Guidelines',subject:'Rules & Regulations',type:'PDF',url:'#'},{title:'Training Video: Parade Basics',subject:'Physical Training',type:'VIDEO',url:'https://youtube.com'}],questions:[],attempt:null,result:null,certificate:null,attendance:92,logs:[{action:'SYSTEM_READY',detail:'Demo data initialized',time:'Today, 09:00'}],notifications:[]};
for(let i=1;i<=28;i++){let name=i===1?'Rahul Kumar':['Amit Singh','Vikram Yadav','Sanjay Kumar','Rohan Mishra','Ankit Verma','Deepak Rai'][i%6]+' '+(i+10);seed.trainees.push({id:i,name,reg:`RPSF/GKP/2026/BT/${String(i).padStart(6,'0')}`,mobile:'98'+String(10000000+i).slice(-8),course:'Basic Training',batch:'GKP-BT-2026-01',status:'ENROLLED',attendance:i===1?92:85+(i%13),email:i===1?'trainee@rpsf.local':`trainee${i}@rpsf.local`})}
const qs=['What is the primary purpose of a parade drill?','Which action should be taken first during an emergency?','A disciplined trainee is expected to be?','Safety equipment must be inspected?','The training centre reporting time is?','Which is essential for physical fitness?','Official instructions should be followed?','Teamwork contributes to?','A roll call is conducted to record?','Training material should be used?'];
seed.courses.push({id:4,code:'DLS-101',name:'Digital Learning & Safety',duration:'6 weeks',pass:50,status:'ACTIVE'});
seed.batches.push({id:4,code:'GKP-DLS-2026-01',course:'Digital Learning & Safety',start:'2026-09-01',end:'2026-10-12',capacity:40,enrolled:0,status:'ACTIVE'});
seed.materials.push({title:'Digital Learning & Safety Handbook (PDF)',subject:'Digital Learning & Safety',type:'PDF',url:'data:text/plain,Digital%20Learning%20%26%20Safety%20Handbook%0A%0AThis%20is%20a%20sample%20downloadable%20learning%20material%20for%20the%20POC.'});
qs.forEach((q,i)=>seed.questions.push({id:i+1,subject:i<5?'Rules & Regulations':'Physical Training',text:q,options:['Maintain order and coordination','Ignore the situation','Avoid instructions','Leave the premises'],correct:'A',marks:1,difficulty:i%3?'MEDIUM':'EASY',status:'ACTIVE'}));
const Store={get(){try{return JSON.parse(localStorage.ttms)||structuredClone(seed)}catch{return structuredClone(seed)}},set(x){localStorage.ttms=JSON.stringify(x)}}; let data=Store.get(), session=JSON.parse(sessionStorage.ttmsUser||'null'), route=location.hash.slice(1)||'/login';
function save(){Store.set(data)} function audit(action,detail){data.logs.unshift({action,detail,time:new Date().toLocaleString()});save()} function badge(s){return `<span class="badge ${String(s).toLowerCase()}">${s}</span>`} function esc(x){return String(x??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function go(x){location.hash=x} function csv(rows,name){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(r=>r.map(x=>`"${String(x).replaceAll('"','""')}"`).join(',')).join('\n')],{type:'text/csv'}));a.download=name;a.click()}
function login(){app.innerHTML=`<main class="login"><section class="login-card"><aside class="brand"><div class="seal">⚜</div><h1>RPSF Training Centre</h1><p>Training & Trainee Management System<br>Gorakhpur · Government Training Administration</p><p class="hint">Secure local POC · 2026</p></aside><form class="login-form" id="login"><h2>Sign in to TTMS</h2><p class="muted">Use your assigned institutional credentials.</p><label>Email / Login ID</label><input name="email" value="admin@rpsf.local" required><label>Password</label><input name="password" type="password" value="Admin@123" required><p class="error" id="err"></p><button class="primary">Sign in</button><p class="hint">New trainee? <a href="#/register">Create a trainee account</a><br>Demo: admin@rpsf.local / Admin@123<br><a href="#" id="reset">Reset demo data</a></p></form></section></main>`;$('#login').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),u=users.find(x=>x[0]===f.get('email')&&x[1]===f.get('password'));if(!u)return $('#err').textContent='Invalid login ID or password.';session={email:u[0],role:u[2],name:u[3]};sessionStorage.ttmsUser=JSON.stringify(session);audit('LOGIN',session.email);go(session.role==='TRAINEE'?'/trainee/dashboard':'/admin/dashboard')};$('#reset').onclick=e=>{e.preventDefault();localStorage.removeItem('ttms');data=structuredClone(seed);location.reload()}}
const adminNav=[['Dashboard','/admin/dashboard'],['Training','/admin/courses'],['Courses','/admin/courses'],['Batches','/admin/batches'],['Trainees','/admin/trainees'],['Pending Verifications','/admin/verifications'],['Attendance','/admin/attendance'],['Learning','/admin/materials'],['Study Material','/admin/materials'],['Examination','/admin/applications'],['Applications','/admin/applications'],['Exam Schedule','/admin/exam-schedule'],['Question Bank','/admin/questions'],['Roll Numbers','/admin/rolls'],['Results','/admin/results'],['Certificates','/admin/certificates'],['Administration','/admin/audit']];
function shell(content,title,sub=''){let nav=(session.role==='TRAINEE'?[['Dashboard','/trainee/dashboard'],['My Profile','/trainee/profile'],['Attendance','/trainee/attendance'],['Study Material','/trainee/materials'],['Examination Form','/trainee/application'],['Online Examination','/trainee/exam'],['Result','/trainee/result'],['Certificate','/trainee/certificate']]:adminNav).map(([n,u])=>n==='Training'||n==='Learning'||n==='Examination'||n==='Results'||n==='Certificates'||n==='Administration'?`<div class="nav-title">${n}</div>`:`<button class="nav ${route===u?'active':''}" onclick="go('${u}')">${n}</button>`).join('');app.innerHTML=`<div class="shell"><aside class="side"><div class="identity"><b>RPSF TTMS</b><small>Training Centre, Gorakhpur</small></div>${nav}</aside><main class="main"><header class="top"><span class="muted">RPSF / Gorakhpur / ${session.role.replace('_',' ')}</span><div class="user"><div class="avatar">${session.name[0]}</div><span>${session.name}</span><button class="linkbtn" onclick="logout()">Sign out</button></div></header><section class="content"><div class="pagehead"><div><h1>${title}</h1><p>${sub}</p></div></div>${content}</section></main></div>`} function logout(){audit('LOGOUT',session.email);sessionStorage.clear();session=null;go('/login')}
function dashboard(){let pending=data.applications.filter(x=>x.status==='SUBMITTED').length,verify=data.trainees.filter(x=>x.status==='PENDING_VERIFICATION').length; shell(`<div class="cards"><div class="card"><span>Total Trainees</span><strong>${data.trainees.length}</strong></div><div class="card"><span>Pending Verifications</span><strong>${verify}</strong>${verify?'<button class="linkbtn" onclick="go(\'/admin/verifications\')">Review now</button>':'<small class="muted">All applications reviewed</small>'}</div><div class="card"><span>Pending Exam Applications</span><strong>${pending}</strong></div><div class="card"><span>Certificates Issued</span><strong>${data.certificate?1:0}</strong></div></div><div class="panel"><h3>Recent Activity</h3>${data.logs.slice(0,7).map(x=>`<div class="activity"><b>${esc(x.action)}</b> · ${esc(x.detail)} <span class="muted">${x.time}</span></div>`).join('')}</div>`, 'Administrative Dashboard','Training operations overview')}
function listCourses(){shell(`<div class="panel"><div class="toolbar"><input class="search" placeholder="Search courses" oninput="filterTable(this,'courseRows')"><button class="primary" onclick="courseForm()">+ Add Course</button></div><div class="tablewrap"><table><thead><tr><th>Code</th><th>Course</th><th>Duration</th><th>Passing %</th><th>Status</th></tr></thead><tbody id="courseRows">${data.courses.map(c=>`<tr><td>${c.code}</td><td><b>${c.name}</b></td><td>${c.duration}</td><td>${c.pass}%</td><td>${badge(c.status)}</td></tr>`).join('')}</tbody></table></div></div>`,'Courses','Course master data')}
function courseForm(){shell(`<div class="panel"><h3>Create Course</h3><form class="form" id="courseForm"><div><label>Course code</label><input name="code" required></div><div><label>Course name</label><input name="name" required></div><div><label>Duration</label><input name="duration" placeholder="12 weeks" required></div><div><label>Passing percentage</label><input name="pass" type="number" value="50" min="0" max="100" required></div><div class="full"><button class="primary">Save Course</button></div></form></div>`,'Create Course','Add a new training programme');$('#courseForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(data.courses.some(x=>x.code===f.code))return alert('Course code must be unique.');data.courses.push({id:Date.now(),...f,status:'ACTIVE'});audit('COURSE_CREATED',f.name);save();go('/admin/courses')}}
function batches(){shell(`<div class="panel"><div class="toolbar"><input class="search" placeholder="Search batches" oninput="filterTable(this,'batchRows')"><button class="primary" onclick="batchForm()">+ Create Batch</button></div><div class="tablewrap"><table><thead><tr><th>Batch</th><th>Course</th><th>Training period</th><th>Capacity</th><th>Enrolled</th><th>Status</th></tr></thead><tbody id="batchRows">${data.batches.map(b=>`<tr><td><b>${b.code}</b></td><td>${b.course}</td><td>${b.start} to ${b.end}</td><td>${b.capacity}</td><td>${b.enrolled} <span class="muted">(${b.capacity-b.enrolled} available)</span></td><td>${badge(b.status)}</td></tr>`).join('')}</tbody></table></div></div>`,'Batches','Training batches and capacity')}
function batchForm(){shell(`<div class="panel"><h3>Create Batch</h3><form class="form" id="batchForm"><div><label>Batch code</label><input name="code" required></div><div><label>Course</label><select name="course">${data.courses.map(x=>`<option>${x.name}</option>`).join('')}</select></div><div><label>Start date</label><input type="date" name="start" required></div><div><label>End date</label><input type="date" name="end" required></div><div><label>Capacity</label><input type="number" name="capacity" value="100" required></div><div class="full"><button class="primary">Save Batch</button></div></form></div>`,'Create Batch');$('#batchForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));data.batches.push({id:Date.now(),...f,enrolled:0,status:'ACTIVE'});audit('BATCH_CREATED',f.code);save();go('/admin/batches')}}
function trainees(){shell(`<div class="panel"><div class="toolbar"><input class="search" placeholder="Search name or registration number" oninput="filterTable(this,'traineeRows')"><button class="primary" onclick="traineeForm()">+ Register Trainee</button></div><div class="tablewrap"><table><thead><tr><th>Registration No</th><th>Name</th><th>Course / Batch</th><th>Mobile</th><th>Enrollment</th><th>Attendance</th><th>Actions</th></tr></thead><tbody id="traineeRows">${data.trainees.map(t=>`<tr><td>${t.reg}</td><td><b>${t.name}</b></td><td>${t.course}<br><small>${t.batch}</small></td><td>${t.mobile}</td><td>${badge(t.status)}</td><td>${t.attendance}%</td><td><button class="linkbtn" onclick="traineeView(${t.id})">View</button></td></tr>`).join('')}</tbody></table></div></div>`,'Trainees','Registration, enrollment and training status')}
function traineeForm(){let next=data.trainees.length+1, reg=`RPSF/GKP/2026/BT/${String(next).padStart(6,'0')}`;shell(`<div class="panel"><h3>Comprehensive trainee registration</h3><form class="form" id="traineeForm"><div><label>Full name</label><input name="name" required></div><div><label>Mobile</label><input name="mobile" pattern="[0-9]{10}" required></div><div><label>Father's name</label><input name="father" required></div><div><label>Email</label><input name="email" type="email"></div><div><label>Course</label><select name="course">${data.courses.map(x=>`<option>${x.name}</option>`).join('')}</select></div><div><label>Batch</label><select name="batch">${data.batches.map(x=>`<option>${x.code}</option>`).join('')}</select></div><div><label>Joining date</label><input name="joining" type="date" required></div><div><label>Qualification</label><input name="qualification" required></div><div class="full"><label>Present address</label><textarea name="address" required></textarea></div><div class="full"><button class="primary">Register and Generate Credentials</button></div></form></div>`,'Register Trainee',`Next registration number: ${reg}`);$('#traineeForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));let id=data.trainees.length+1,t={id,...f,reg:`RPSF/GKP/2026/BT/${String(id).padStart(6,'0')}`,status:'ENROLLED',attendance:0};data.trainees.push(t);let b=data.batches.find(x=>x.code===f.batch);if(b)b.enrolled++;audit('TRAINEE_CREATED',`${t.name} · ${t.reg}`);save();shell(`<div class="panel"><div class="notice"><b>Registration Successful</b><br><br>Registration No: <b>${t.reg}</b><br>Login ID: <b>${String(id).padStart(6,'0')}</b><br>Temporary password: <b>Set during account activation</b></div><button class="primary" onclick="go('/admin/trainees')">Back to Trainees</button></div>`,'Trainee Registered')}}
function traineeView(id){let t=data.trainees.find(x=>x.id===id);shell(`<div class="cards"><div class="card"><span>Registration Number</span><strong style="font-size:16px">${t.reg}</strong></div><div class="card"><span>Enrollment</span><strong>${t.status}</strong></div><div class="card"><span>Attendance</span><strong>${t.attendance}%</strong><div class="progress"><i style="width:${t.attendance}%"></i></div></div><div class="card"><span>Batch</span><strong style="font-size:16px">${t.batch}</strong></div></div><div class="panel"><h3>${t.name}</h3><table><tr><td>Mobile</td><td>${t.mobile}</td></tr><tr><td>Email</td><td>${t.email||'—'}</td></tr><tr><td>Course</td><td>${t.course}</td></tr><tr><td>Father's Name</td><td>${t.father||'—'}</td></tr></table></div>`,'Trainee Profile','Enrollment details and academic record')}
function attendance(){shell(`<div class="panel"><div class="toolbar"><div><b>GKP-BT-2026-01</b> · 21 Aug 2026</div><button class="secondary" onclick="window.print()">Print Attendance Sheet</button></div><p class="muted">Daily attendance · Period 1</p><div class="tablewrap"><table><thead><tr><th>Roll No</th><th>Registration No</th><th>Name</th><th>Status</th></tr></thead><tbody>${data.trainees.slice(0,12).map((t,i)=>`<tr><td>${data.rolls.find(x=>x.traineeId===t.id)?.number||'—'}</td><td>${t.reg}</td><td>${t.name}</td><td><select onchange="setAttend(${t.id},this.value)"><option ${i%8?'selected':''}>PRESENT</option><option ${i%8?'':'selected'}>ABSENT</option><option>LEAVE</option><option>MEDICAL</option><option>LATE</option></select></td></tr>`).join('')}</tbody></table></div><p><button class="primary" onclick="audit('ATTENDANCE_SAVED','GKP-BT-2026-01');alert('Attendance saved successfully.')">Save Attendance</button></p></div>`,'Attendance','Record and export daily attendance')};function setAttend(id,value){audit('ATTENDANCE_UPDATED',`${id}: ${value}`)}
function materials(){shell(`<div class="panel"><div class="toolbar"><input class="search" placeholder="Search study material" oninput="filterTable(this,'materialRows')">${session.role==='TRAINEE'?'':`<button class="primary" onclick="materialForm()">+ Add Material</button>`}</div><div class="tablewrap"><table><thead><tr><th>Title</th><th>Subject</th><th>Type</th><th>Available to trainees</th></tr></thead><tbody id="materialRows">${data.materials.map(m=>`<tr><td><b>${m.title}</b></td><td>${m.subject}</td><td>${badge(m.type==='PDF'?'PDF':'VIDEO')}</td><td><a class="linkbtn" href="${m.url}" target="_blank">Open resource</a></td></tr>`).join('')}</tbody></table></div></div>`,'Study Material','Published learning resources')}
function materialForm(){shell(`<div class="panel"><h3>Publish study material</h3><form class="form" id="matForm"><div><label>Title</label><input name="title" required></div><div><label>Subject</label><input name="subject" required></div><div><label>Type</label><select name="type"><option>PDF</option><option>VIDEO</option></select></div><div><label>PDF/YouTube URL</label><input name="url" type="url" required></div><div class="full"><button class="primary">Publish Material</button></div></form></div>`,'Add Study Material');$('#matForm').onsubmit=e=>{e.preventDefault();let m=Object.fromEntries(new FormData(e.target));data.materials.push(m);audit('MATERIAL_PUBLISHED',m.title);save();go('/admin/materials')}}
function application(){let a=data.applications.find(x=>x.traineeId===1);shell(a?`<div class="panel"><h3>Final Assessment – Basic Training</h3><p>Application no. <b>${a.number}</b></p><p>Status: ${badge(a.status)}</p><p class="muted">Exam Cell will verify eligibility and allocate your roll number.</p></div>`:`<div class="panel"><h3>Examination Form</h3><p class="notice">Rahul Kumar · RPSF/GKP/2026/BT/000001 · Basic Training · GKP-BT-2026-01</p><form id="appForm"><label><input type="checkbox" required> I confirm that the information above is correct.</label><p><button class="primary">Submit Examination Application</button></p></form></div>`,'Examination Form','Final Assessment – Basic Training');let f=$('#appForm');if(f)f.onsubmit=e=>{e.preventDefault();data.applications.push({traineeId:1,number:'APP/GKP/2026/0001',name:'Rahul Kumar',status:'SUBMITTED'});data.notifications.push('Examination application submitted');audit('EXAM_APPLICATION_SUBMITTED','Rahul Kumar');save();application()}}
function applications(){shell(`<div class="panel"><div class="toolbar"><b>Final Assessment – Basic Training</b><span>${data.applications.length} applications</span></div><div class="tablewrap"><table><thead><tr><th>Application No</th><th>Trainee</th><th>Status</th><th>Action</th></tr></thead><tbody>${data.applications.length?data.applications.map(a=>`<tr><td>${a.number}</td><td>${a.name}</td><td>${badge(a.status)}</td><td>${a.status==='SUBMITTED'?`<button class="primary" onclick="approveApp(${a.traineeId})">Approve</button>`:'Verified'}</td></tr>`).join(''):'<tr><td colspan="4" class="muted">No applications submitted yet. Login as Rahul Kumar to submit one.</td></tr>'}</tbody></table></div></div>`,'Examination Applications','Review trainee examination forms')};function approveApp(id){let a=data.applications.find(x=>x.traineeId===id);a.status='APPROVED';data.notifications.push('Examination application approved');audit('APPLICATION_APPROVED',a.name);save();applications()}
function rolls(){let approved=data.applications.filter(x=>x.status==='APPROVED');shell(`<div class="panel"><div class="toolbar"><div><b>Final Assessment – Basic Training</b><br><small>Total approved candidates: ${approved.length} · Roll numbers generated: ${data.rolls.length}</small></div><button class="primary" onclick="generateRolls()">Generate Roll Numbers</button></div><div class="tablewrap"><table><thead><tr><th>S.No</th><th>Roll No</th><th>Registration No</th><th>Name</th><th>Batch</th><th>Signature</th></tr></thead><tbody>${data.rolls.map((r,i)=>{let t=data.trainees.find(x=>x.id===r.traineeId);return `<tr><td>${i+1}</td><td><b>${r.number}</b></td><td>${t.reg}</td><td>${t.name}</td><td>${t.batch}</td><td>____________</td></tr>`}).join('')||'<tr><td colspan="6" class="muted">Generate rolls after application approval.</td></tr>'}</tbody></table></div><p><button class="secondary" onclick="window.print()">Print Roll List / Save PDF</button></p></div>`,'Roll Numbers & Roll List','Allocate unique examination roll numbers')};function generateRolls(){data.applications.filter(x=>x.status==='APPROVED').forEach(a=>{if(!data.rolls.some(r=>r.traineeId===a.traineeId))data.rolls.push({traineeId:a.traineeId,number:`RPSF/GKP/2026/${String(data.rolls.length+1).padStart(4,'0')}`})});audit('ROLL_NUMBERS_GENERATED','Final Assessment – Basic Training');save();rolls()}
function questions(){shell(`<div class="panel"><div class="toolbar"><input class="search" placeholder="Search questions" oninput="filterTable(this,'qRows')"><button class="primary" onclick="questionForm()">+ Add Question</button></div><div class="tablewrap"><table><thead><tr><th>Question</th><th>Subject</th><th>Correct</th><th>Marks</th><th>Difficulty</th><th>Status</th></tr></thead><tbody id="qRows">${data.questions.map(q=>`<tr><td>${q.text}</td><td>${q.subject}</td><td>${q.correct}</td><td>${q.marks}</td><td>${q.difficulty}</td><td>${badge(q.status)}</td></tr>`).join('')}</tbody></table></div><p><button class="secondary" onclick="csv([['Question','Subject','Correct'],...data.questions.map(q=>[q.text,q.subject,q.correct])],'question-bank.csv')">Export CSV</button></p></div>`,'Question Bank','Active questions: '+data.questions.length)}
function questionForm(){shell(`<div class="panel"><h3>Add objective question</h3><form class="form" id="qForm"><div class="full"><label>Question text</label><textarea name="text" required></textarea></div><div><label>Subject</label><input name="subject" required></div><div><label>Difficulty</label><select name="difficulty"><option>EASY</option><option>MEDIUM</option><option>HARD</option></select></div>${['A','B','C','D'].map(x=>`<div><label>Option ${x}</label><input name="${x}" required></div>`).join('')}<div><label>Correct answer</label><select name="correct"><option>A</option><option>B</option><option>C</option><option>D</option></select></div><div><label>Marks</label><input type="number" name="marks" value="1" min="1"></div><div class="full"><button class="primary">Save Question</button></div></form></div>`,'Add Question');$('#qForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));data.questions.push({id:Date.now(),text:f.text,subject:f.subject,options:['A','B','C','D'].map(x=>f[x]),correct:f.correct,marks:+f.marks,difficulty:f.difficulty,status:'ACTIVE'});audit('QUESTION_CREATED',f.subject);save();go('/admin/questions')}}
function exam(){let a=data.applications.find(x=>x.traineeId===1), r=data.rolls.find(x=>x.traineeId===1);if(data.result)return shell(`<div class="panel"><h3>Examination completed</h3><p>Your answers are locked and evaluation is complete.</p><button class="primary" onclick="go('/trainee/result')">View Result</button></div>`,'Online Examination');if(!a||a.status!=='APPROVED'||!r)return shell(`<div class="panel"><h3>Not yet eligible</h3><p class="muted">A submitted and approved examination form plus a generated roll number is required to start the exam.</p></div>`,'Online Examination');let q=data.questions.slice(0,10), attempt=data.attempt||{answers:{},start:Date.now(),review:{}};data.attempt=attempt;save();let current=0;function draw(){let x=q[current];shell(`<div class="exam"><div class="exam-top"><b>FINAL ASSESSMENT 2026</b><span class="timer" id="timer">Time Remaining: 60:00</span></div><div class="panel"><div class="muted">Question ${current+1} of ${q.length}</div><div class="question">${esc(x.text)}</div>${x.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${'ABCD'[i]}" ${attempt.answers[x.id]==='ABCD'[i]?'checked':''}> ${'ABCD'[i]}. ${esc(o)}</label>`).join('')}<p class="actions"><button class="secondary" onclick="examMove(-1)" ${current?'':'disabled'}>Previous</button><button class="secondary" onclick="markReview(${x.id})">Mark for Review</button><button class="primary" onclick="examMove(1)">${current===q.length-1?'Save & Review':'Save & Next'}</button></p><hr><div class="palette">${q.map((z,i)=>`<button class="${attempt.answers[z.id]?'answered':''}" onclick="examJump(${i})">${i+1}</button>`).join('')}</div><p><button class="primary" onclick="submitExam()">Submit Examination</button></p></div></div>`,'Online Examination','Answers are saved automatically');document.querySelectorAll('[name=answer]').forEach(e=>e.onchange=()=>{attempt.answers[x.id]=e.target.value;save();draw()});let remain=Math.max(0,3600000-(Date.now()-attempt.start));let tick=setInterval(()=>{let z=$('#timer');if(!z)return clearInterval(tick);z.textContent='Time Remaining: '+new Date(remain).toISOString().slice(14,19);if((remain-=1000)<=0){clearInterval(tick);submitExam()}},1000)}window.examMove=d=>{let chosen=$('[name=answer]:checked');if(chosen)attempt.answers[q[current].id]=chosen.value;current=Math.min(q.length-1,Math.max(0,current+d));save();draw()};window.examJump=i=>{current=i;draw()};window.markReview=id=>{attempt.review[id]=true;save();alert('Question marked for review.')};draw()}
function submitExam(){if(!confirm('Submit your examination? Answers cannot be changed afterwards.'))return;let q=data.questions.slice(0,10), ans=data.attempt.answers,correct=q.filter(x=>ans[x.id]===x.correct).length,attempted=Object.keys(ans).length,marks=correct;data.result={correct,attempted,total:q.length,marks,percentage:marks/q.length*100,outcome:marks/q.length*100>=50?'PASS':'FAIL',status:'DRAFT'};data.attempt.completed=true;data.notifications.push('Examination completed. Result pending publication.');audit('EXAM_SUBMITTED','Rahul Kumar: '+marks+'/'+q.length);save();go('/trainee/result')}
function results(){let r=data.result, body='<p class="muted">No completed examinations yet.</p>';if(r){let action=r.status==='DRAFT'?'<button class="primary" onclick="publishResult()">Verify & Publish</button>':'Published';body=`<h3>Final Assessment – Basic Training</h3><div class="cards"><div class="card"><span>Candidates Appeared</span><strong>1</strong></div><div class="card"><span>Passed</span><strong>${r.outcome==='PASS'?1:0}</strong></div><div class="card"><span>Pass Percentage</span><strong>${r.outcome==='PASS'?100:0}%</strong></div></div><table><tr><th>Trainee</th><th>Marks</th><th>Percentage</th><th>Result</th><th>Publication</th><th>Action</th></tr><tr><td>Rahul Kumar</td><td>${r.marks}/${r.total}</td><td>${r.percentage}%</td><td>${badge(r.outcome)}</td><td>${badge(r.status)}</td><td>${action}</td></tr></table>`}shell(`<div class="panel">${body}</div>`,'Result Processing','Auto-evaluation and publication control')};function publishResult(){data.result.status='PUBLISHED';data.notifications.push('Result published');audit('RESULT_PUBLISHED','Rahul Kumar · '+data.result.outcome);save();results()}
function traineeDashboard(){let t=data.trainees[0],a=data.applications[0],r=data.result; shell(`<div class="cards"><div class="card"><span>Registration Number</span><strong style="font-size:15px">${t.reg}</strong></div><div class="card"><span>Attendance</span><strong>${t.attendance}%</strong><div class="progress"><i style="width:${t.attendance}%"></i></div></div><div class="card"><span>Exam</span><strong style="font-size:17px">${a?a.status:'Not applied'}</strong></div><div class="card"><span>Result</span><strong>${r&&r.status==='PUBLISHED'?r.outcome:'Pending'}</strong></div></div><div class="panel"><h3>Welcome, Rahul Kumar</h3><p>Course: <b>Basic Training</b> · Batch: <b>GKP-BT-2026-01</b></p><div class="actions"><button class="secondary" onclick="go('/trainee/application')">Examination Form</button><button class="secondary" onclick="go('/trainee/materials')">Study Material</button><button class="secondary" onclick="go('/trainee/exam')">Online Examination</button></div></div>`,'Trainee Dashboard','Your training and examination status')}
function traineeResult(){let r=data.result;shell(`<div class="panel">${!r?'<p class="muted">No result is available. Complete the examination first.</p>':r.status!=='PUBLISHED'?'<h3>Result Pending</h3><p>Your examination has been evaluated. The Exam Cell will publish it after verification.</p>':`<h3>Final Assessment – Basic Training</h3><div class="cards"><div class="card"><span>Marks obtained</span><strong>${r.marks}/${r.total}</strong></div><div class="card"><span>Percentage</span><strong>${r.percentage}%</strong></div><div class="card"><span>Result</span><strong>${r.outcome}</strong></div><div class="card"><span>Certificate</span><strong style="font-size:16px">${data.certificate?'Available':'Eligible'}</strong></div></div><p>${r.outcome==='PASS'?'<button class="primary" onclick="go(\'/trainee/certificate\')">View Certificate</button>':'Please contact the Exam Cell for guidance.'}</p>`}</div>`,'My Result','Published examination result')}
function certificates(){let r=data.result,body='<p class="muted">Certificates are available after a published PASS result.</p>';if(r?.status==='PUBLISHED'&&r.outcome==='PASS'){let cert=data.certificate?data.certificate.number:'Not issued',action=data.certificate?'Issued':'<button class="primary" onclick="issueCertificate()">Generate Certificate</button>';body=`<h3>Certificate eligible candidate</h3><table><tr><th>Name</th><th>Result</th><th>Certificate</th><th>Action</th></tr><tr><td>Rahul Kumar</td><td>${badge(r.outcome)}</td><td>${cert}</td><td>${action}</td></tr></table>`}shell(`<div class="panel">${body}</div>`,'Certificates','Generate and manage issued certificates')};function issueCertificate(){data.certificate={number:'RPSF/GKP/CERT/2026/000001',issued:new Date().toLocaleDateString('en-GB')};audit('CERTIFICATE_GENERATED',data.certificate.number);data.notifications.push('Certificate is available');save();certificates()}
function certificate(){if(!data.certificate)return shell(`<div class="panel"><p class="muted">No certificate is currently available.</p></div>`,'My Certificate');let c=data.certificate;shell(`<div class="certificate"><div class="qr"></div><h1>Certificate of Training</h1><p>This is to certify that</p><h2>Rahul Kumar</h2><p>Registration No: ${data.trainees[0].reg}</p><p>has successfully completed <b>Basic Training</b><br>at RPSF Training Centre, Gorakhpur</p><p>Result: <b>PASS</b> · Certificate No: <b>${c.number}</b> · Issue date: ${c.issued}</p><p>Authorized Signatory</p></div><p><button class="primary" onclick="window.print()">Print / Save as PDF</button> <button class="secondary" onclick="go('/certificate/verify/'+data.certificate.number)">Verify Certificate</button></p>`,'My Certificate','Digitally verifiable training record')}
function verify(){let c=data.certificate;app.innerHTML=`<main class="public"><div class="panel"><h1>Certificate Verification</h1>${c?`<p class="notice"><b>VALID CERTIFICATE</b></p><table><tr><td>Certificate No</td><td><b>${c.number}</b></td></tr><tr><td>Name</td><td>Rahul Kumar</td></tr><tr><td>Course</td><td>Basic Training</td></tr><tr><td>Training Centre</td><td>RPSF Training Centre, Gorakhpur</td></tr><tr><td>Result</td><td>${badge('PASS')}</td></tr><tr><td>Status</td><td>${badge('VALID')}</td></tr></table>`:`<p class="error">Certificate was not found or has not been issued.</p>`}<p><button class="secondary" onclick="go('/login')">Back to TTMS</button></p></div></main>`}
function auditLog(){shell(`<div class="panel"><div class="toolbar"><b>System Audit Log</b><button class="secondary" onclick="csv([['Action','Detail','Time'],...data.logs.map(x=>[x.action,x.detail,x.time])],'audit-log.csv')">Export CSV</button></div><table><thead><tr><th>Action</th><th>Entity / Detail</th><th>Timestamp</th></tr></thead><tbody>${data.logs.map(x=>`<tr><td>${badge(x.action)}</td><td>${x.detail}</td><td>${x.time}</td></tr>`).join('')}</tbody></table></div>`,'Audit Logs','Accountability record for key system actions')}
function filterTable(i,id){let q=i.value.toLowerCase();document.querySelectorAll('#'+id+' tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))}
function selfRegister(){app.innerHTML=`<main class="login"><section class="login-card"><aside class="brand"><div class="seal">⚜</div><h1>Self Registration</h1><p>Apply for an RPSF training programme. Your profile will be activated after administrative verification.</p></aside><form class="login-form" id="selfReg"><h2>Trainee application</h2><p class="muted">All fields marked below are used for verification.</p><label>Full name</label><input name="name" required><label>Mobile number</label><input name="mobile" pattern="[0-9]{10}" required><label>Email address</label><input name="email" type="email" required><label>Choose course</label><select name="course"><option>Digital Learning & Safety</option><option>Basic Training</option></select><label>Choose batch</label><select name="batch"><option>GKP-DLS-2026-01</option><option>GKP-BT-2026-02</option></select><label>Qualification</label><input name="qualification" required><p class="error" id="err"></p><button class="primary">Submit for Verification</button><p class="hint"><a href="#/login">Return to sign in</a></p></form></section></main>`;$('#selfReg').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),id=data.trainees.length+1,t={id,...f,reg:`RPSF/GKP/2026/SR/${String(id).padStart(6,'0')}`,status:'PENDING_VERIFICATION',attendance:0};if(data.trainees.some(x=>x.email===t.email))return $('#err').textContent='An application already exists for this email.';data.trainees.push(t);audit('SELF_REGISTRATION_SUBMITTED',`${t.name} · ${t.reg}`);save();app.innerHTML=`<main class="login"><section class="login-card"><aside class="brand"><h1>Application submitted</h1><p>Your application is waiting for administrative verification.</p></aside><div class="login-form"><h2>Thank you, ${esc(t.name)}</h2><div class="notice">Your application number is <b>${t.reg}</b>.<br><br>An administrator will verify your details. Learning, schedules and assessments unlock after approval.</div><a class="primary" href="#/login">Return to sign in</a></div></section></main>`}}
function trainees(){shell(`<div class="panel"><div class="toolbar"><input class="search" placeholder="Search name or registration number" oninput="filterTable(this,'traineeRows')"><button class="primary" onclick="traineeForm()">+ Register Trainee</button></div><div class="tablewrap"><table><thead><tr><th>Registration No</th><th>Name</th><th>Course / Batch</th><th>Mobile</th><th>Verification</th><th>Learning</th><th>Actions</th></tr></thead><tbody id="traineeRows">${data.trainees.map(t=>`<tr><td>${t.reg}</td><td><b>${t.name}</b><br><small>${t.email||''}</small></td><td>${t.course}<br><small>${t.batch}</small></td><td>${t.mobile}</td><td>${badge(t.status)}</td><td>${t.status==='PENDING_VERIFICATION'?'Locked':t.attendance+'%'}</td><td>${t.status==='PENDING_VERIFICATION'?`<button class="primary" onclick="verifyTrainee(${t.id})">Verify & Activate</button>`:`<button class="linkbtn" onclick="traineeView(${t.id})">View</button>`}</td></tr>`).join('')}</tbody></table></div></div>`,'Trainees','Verify self-registered applicants before learning access')}
function verifyTrainee(id){let t=data.trainees.find(x=>x.id===id);t.status='ENROLLED';let b=data.batches.find(x=>x.code===t.batch);if(b)b.enrolled++;data.notifications.push(`${t.name} verified and learning access activated`);audit('TRAINEE_VERIFIED',`${t.name} · ${t.reg}`);save();trainees()}
function verifications(){let pending=data.trainees.filter(x=>x.status==='PENDING_VERIFICATION');shell(`<div class="panel"><div class="toolbar"><div><b>Self-registration review queue</b><br><small class="muted">Only verified trainees receive learning, scheduling and examination access.</small></div><span>${pending.length} pending</span></div>${pending.length?`<div class="tablewrap"><table><thead><tr><th>Application / Registration</th><th>Applicant</th><th>Contact</th><th>Requested Course</th><th>Qualification</th><th>Decision</th></tr></thead><tbody>${pending.map(t=>`<tr><td><b>${t.reg}</b></td><td>${t.name}</td><td>${t.email}<br>${t.mobile}</td><td>${t.course}<br><small>${t.batch}</small></td><td>${t.qualification||'—'}</td><td><button class="primary" onclick="verifyFromQueue(${t.id})">Verify & Activate</button> <button class="secondary" onclick="rejectTrainee(${t.id})">Reject</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="notice">There are no pending trainee verifications. New self-registration applications will appear here immediately.</div>`}</div>`,'Pending Verifications','Review and activate self-registered trainee profiles')}
function verifyFromQueue(id){let t=data.trainees.find(x=>x.id===id);t.status='ENROLLED';let b=data.batches.find(x=>x.code===t.batch);if(b)b.enrolled++;data.notifications.push(`${t.name} verified and learning access activated`);audit('TRAINEE_VERIFIED',`${t.name} · ${t.reg}`);save();verifications()}
function rejectTrainee(id){let t=data.trainees.find(x=>x.id===id);if(!confirm(`Reject the application from ${t.name}?`))return;t.status='REJECTED';audit('TRAINEE_REGISTRATION_REJECTED',`${t.name} · ${t.reg}`);save();verifications()}
function traineeDashboard(){let t=data.trainees[0],a=data.applications[0],r=data.result; shell(`<div class="cards"><div class="card"><span>Learning Progress</span><strong>68%</strong><div class="progress"><i style="width:68%"></i></div></div><div class="card"><span>Attendance</span><strong>${t.attendance}%</strong><div class="progress"><i style="width:${t.attendance}%"></i></div></div><div class="card"><span>Next Examination</span><strong style="font-size:16px">12 Oct 2026</strong></div><div class="card"><span>Result</span><strong>${r&&r.status==='PUBLISHED'?r.outcome:'Pending'}</strong></div></div><div class="panel"><h3>Resume Learning</h3><p><b>Basic Training · Module 4: Safety Procedures</b></p><div class="progress"><i style="width:68%"></i></div><p class="muted">68% complete · Last activity: Safety Guidelines</p><button class="primary" onclick="go('/trainee/materials')">Continue Learning</button></div><div class="cards" style="margin-top:18px"><div class="panel" style="margin:0"><h3>Weekly Class Schedule</h3><p><b>Monday</b> · 09:00–11:00 · Physical Training</p><p><b>Wednesday</b> · 10:00–12:00 · Rules & Regulations</p><p><b>Friday</b> · 14:00–16:00 · Safety Drill</p></div><div class="panel" style="margin:0"><h3>Examination Calendar</h3><p><b>05 Oct 2026</b> · Application deadline</p><p><b>12 Oct 2026</b> · Final Assessment, 10:00</p><p><b>20 Oct 2026</b> · Results publication</p></div></div>`,'Trainee Dashboard','Welcome, Rahul Kumar · Your personal learning centre')}
function examConfig(){return data.examConfig||{name:'Final Assessment – Basic Training',date:'2026-10-12',start:'10:00',duration:60,status:'SCHEDULED'}}
function examSchedule(){let x=examConfig();shell(`<div class="panel"><h3>Examination schedule and access control</h3><p class="notice">Only the administrator can set the exam date and start time. Eligible trainees cannot enter before the configured time.</p><form class="form" id="scheduleForm"><div><label>Examination name</label><input name="name" value="${esc(x.name)}" required></div><div><label>Status</label><select name="status"><option ${x.status==='SCHEDULED'?'selected':''}>SCHEDULED</option><option ${x.status==='CLOSED'?'selected':''}>CLOSED</option></select></div><div><label>Exam date</label><input type="date" name="date" value="${x.date}" required></div><div><label>Strict start time</label><input type="time" name="start" value="${x.start}" required></div><div><label>Duration (minutes)</label><input type="number" name="duration" value="${x.duration}" min="1" required></div><div class="full"><button class="primary">Save Schedule</button></div></form></div>`,'Exam Schedule','Administrator-controlled examination timing');$('#scheduleForm').onsubmit=e=>{e.preventDefault();data.examConfig=Object.fromEntries(new FormData(e.target));data.examConfig.duration=+data.examConfig.duration;audit('EXAM_SCHEDULE_UPDATED',`${data.examConfig.date} ${data.examConfig.start}`);save();examSchedule()}}
function traineeView(id){let t=data.trainees.find(x=>x.id===id);shell(`<div class="cards"><div class="card"><span>Registration Number</span><strong style="font-size:16px">${t.reg}</strong></div><div class="card"><span>Enrollment</span><strong>${t.status}</strong></div><div class="card"><span>Attendance</span><strong>${t.attendance}%</strong><div class="progress"><i style="width:${t.attendance}%"></i></div></div><div class="card"><span>Batch</span><strong style="font-size:16px">${t.batch}</strong></div></div><div class="panel"><div class="toolbar"><h3>${esc(t.name)}</h3><button class="primary" onclick="traineeEdit(${t.id})">Edit Trainee Information</button></div><table><tr><td>Mobile</td><td>${esc(t.mobile)}</td></tr><tr><td>Email</td><td>${esc(t.email||'—')}</td></tr><tr><td>Course</td><td>${esc(t.course)}</td></tr><tr><td>Father's Name</td><td>${esc(t.father||'—')}</td></tr><tr><td>Mother's Name</td><td>${esc(t.mother||'—')}</td></tr><tr><td>Address</td><td>${esc(t.address||'—')}</td></tr><tr><td>Documents</td><td>${(t.documents||[]).map(esc).join(', ')||'No documents recorded'}</td></tr></table></div>`,'Trainee Profile','Manage personal, parent and enrollment information')}
function traineeEdit(id){let t=data.trainees.find(x=>x.id===id);shell(`<div class="panel"><h3>Edit trainee information</h3><form class="form" id="editTrainee"><div><label>Full name</label><input name="name" value="${esc(t.name)}" required></div><div><label>Mobile</label><input name="mobile" value="${esc(t.mobile)}" required></div><div><label>Email</label><input name="email" type="email" value="${esc(t.email||'')}"></div><div><label>Father's name</label><input name="father" value="${esc(t.father||'')}"></div><div><label>Mother's name</label><input name="mother" value="${esc(t.mother||'')}"></div><div><label>Qualification</label><input name="qualification" value="${esc(t.qualification||'')}"></div><div class="full"><label>Address</label><textarea name="address">${esc(t.address||'')}</textarea></div><div class="full"><button class="primary">Save Changes</button> <button type="button" class="secondary" onclick="traineeView(${id})">Cancel</button></div></form></div>`,'Edit Trainee','Changes are recorded in the audit log');$('#editTrainee').onsubmit=e=>{e.preventDefault();Object.assign(t,Object.fromEntries(new FormData(e.target)));audit('TRAINEE_UPDATED',`${t.name} · ${t.reg}`);save();traineeView(id)}}
function application(){let t=data.trainees[0],a=data.applications.find(x=>x.traineeId===1),x=examConfig();if(a&&a.status!=='DRAFT')return shell(`<div class="panel"><h3>${esc(x.name)}</h3><p>Application no. <b>${a.number}</b></p><p>Status: ${badge(a.status)}</p><p>Documents: ${(a.documents||[]).map(esc).join(', ')||'None attached'}</p>${a.remarks?`<p class="notice">Admin remarks: ${esc(a.remarks)}</p>`:''}<button class="secondary" onclick="applicationEdit()">Edit Application</button></div>`,'Examination Form','Review and update your submitted application');applicationEdit()}
function applicationEdit(){let t=data.trainees[0],a=data.applications.find(x=>x.traineeId===1)||{traineeId:1,number:'APP/GKP/2026/0001',name:t.name,status:'DRAFT',documents:[]};shell(`<div class="panel"><h3>Detailed Examination Application</h3><p class="notice">${esc(t.reg)} · ${esc(t.course)} · ${esc(t.batch)}</p><form class="form" id="appForm"><div><label>Candidate name</label><input name="name" value="${esc(a.name||t.name)}" required></div><div><label>Date of birth</label><input name="dob" type="date" value="${a.dob||''}" required></div><div><label>Mobile</label><input name="mobile" value="${esc(a.mobile||t.mobile)}" required></div><div><label>Email</label><input name="email" type="email" value="${esc(a.email||t.email)}" required></div><div><label>Father's name</label><input name="father" value="${esc(a.father||t.father||'')}" required></div><div><label>Mother's name</label><input name="mother" value="${esc(a.mother||t.mother||'')}" required></div><div class="full"><label>Current address</label><textarea name="address" required>${esc(a.address||t.address||'')}</textarea></div><div><label>Identity document (PDF/JPG/PNG)</label><input id="idDoc" type="file" accept=".pdf,.jpg,.jpeg,.png"></div><div><label>Qualification document (PDF/JPG/PNG)</label><input id="qualDoc" type="file" accept=".pdf,.jpg,.jpeg,.png"></div><div class="full"><label><input type="checkbox" name="confirm" required> I confirm that the details and documents are accurate.</label></div><div class="full"><button class="primary">${a.status==='DRAFT'?'Submit Application':'Save Updated Application'}</button></div></form></div>`,'Examination Application','Basic, parent, contact and document information');$('#appForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));delete f.confirm;let docs=[...($('#idDoc').files),...($('#qualDoc').files)].map(z=>z.name);Object.assign(a,f,{name:f.name,documents:docs.length?docs:(a.documents||[]),status:'SUBMITTED'});if(!data.applications.includes(a))data.applications.push(a);audit('EXAM_APPLICATION_SUBMITTED',`${a.name} · ${a.number}`);save();application()}}
function applications(){shell(`<div class="panel"><div class="toolbar"><b>${esc(examConfig().name)}</b><span>${data.applications.length} applications</span></div><div class="tablewrap"><table><thead><tr><th>Application No</th><th>Trainee</th><th>Documents</th><th>Status</th><th>Admin decision</th></tr></thead><tbody>${data.applications.length?data.applications.map(a=>`<tr><td>${a.number}</td><td>${esc(a.name)}</td><td>${(a.documents||[]).map(esc).join(', ')||'—'}</td><td>${badge(a.status)}</td><td>${a.status==='SUBMITTED'?`<button class="primary" onclick="approveApp(${a.traineeId})">Approve</button> <button class="secondary" onclick="applicationRemarks(${a.traineeId})">Reject / Remarks</button>`:`<button class="linkbtn" onclick="applicationRemarks(${a.traineeId})">View / Update Remarks</button>`}</td></tr>`).join(''):'<tr><td colspan="5" class="muted">No applications submitted yet.</td></tr>'}</tbody></table></div></div>`,'Examination Applications','Review detailed applicant and document information')}
function applicationRemarks(id){let a=data.applications.find(x=>x.traineeId===id),remark=prompt('Enter administrator remarks (required when rejecting):',a.remarks||'');if(remark===null)return;a.remarks=remark;if(confirm('Reject this examination application? Select Cancel to save remarks without changing status.'))a.status='REJECTED';audit(a.status==='REJECTED'?'EXAM_APPLICATION_REJECTED':'EXAM_APPLICATION_REMARKED',a.name);save();applications()}
function approveApp(id){let a=data.applications.find(x=>x.traineeId===id);a.status='APPROVED';a.remarks=a.remarks||'Documents verified and application approved.';data.notifications.push('Examination application approved');audit('APPLICATION_APPROVED',a.name);save();applications()}
function questions(){let papers=data.questionPapers||[];shell(`<div class="panel"><div class="toolbar"><input class="search" placeholder="Search questions" oninput="filterTable(this,'qRows')"><div class="actions"><button class="secondary" onclick="paperUpload()">Upload Question Paper PDF</button><button class="primary" onclick="questionForm()">+ Create Question</button></div></div>${papers.length?`<p class="notice">Question paper PDFs: ${papers.map(esc).join(', ')}</p>`:''}<div class="tablewrap"><table><thead><tr><th>Type</th><th>Question</th><th>Subject</th><th>Answer / Evaluation</th><th>Marks</th><th>Status</th></tr></thead><tbody id="qRows">${data.questions.map(q=>`<tr><td>${badge(q.type||'MCQ')}</td><td>${esc(q.text)}</td><td>${esc(q.subject)}</td><td>${q.type==='SUBJECTIVE'?'Manual evaluation':esc(q.correct)}</td><td>${q.marks}</td><td>${badge(q.status)}</td></tr>`).join('')}</tbody></table></div><p><button class="secondary" onclick="csv([['Type','Question','Subject','Answer'],...data.questions.map(q=>[q.type||'MCQ',q.text,q.subject,q.correct||'Manual'])],'question-bank.csv')">Export CSV</button></p></div>`,'Question Bank Creator','Create MCQ and subjective questions, or attach PDF question papers')}
function paperUpload(){shell(`<div class="panel"><h3>Upload question paper PDF</h3><form id="paperForm"><label>Question paper (PDF only)</label><input id="paper" type="file" accept="application/pdf,.pdf" required><p class="hint">The local POC records the uploaded filename. A production backend should store the file in protected object storage.</p><button class="primary">Attach PDF Paper</button></form></div>`,'Question Paper Upload');$('#paperForm').onsubmit=e=>{e.preventDefault();let f=$('#paper').files[0];if(!f||!f.name.toLowerCase().endsWith('.pdf'))return alert('Please select a PDF file.');data.questionPapers=data.questionPapers||[];data.questionPapers.push(f.name);audit('QUESTION_PAPER_PDF_UPLOADED',f.name);save();go('/admin/questions')}}
function questionForm(){shell(`<div class="panel"><h3>Create question</h3><form class="form" id="qForm"><div><label>Question type</label><select name="type" id="qType" onchange="questionTypeFields()"><option value="MCQ">MCQ (objective)</option><option value="SUBJECTIVE">Subjective / descriptive</option></select></div><div><label>Subject</label><input name="subject" required></div><div class="full"><label>Question text</label><textarea name="text" required></textarea></div><div><label>Difficulty</label><select name="difficulty"><option>EASY</option><option>MEDIUM</option><option>HARD</option></select></div><div><label>Marks</label><input type="number" name="marks" value="1" min="1"></div><div id="mcqFields" class="full form">${['A','B','C','D'].map(x=>`<div><label>Option ${x}</label><input name="${x}"></div>`).join('')}<div><label>Correct answer</label><select name="correct"><option>A</option><option>B</option><option>C</option><option>D</option></select></div></div><div id="subjectiveFields" class="full" hidden><label>Evaluation guidance / model answer</label><textarea name="guidance"></textarea></div><div class="full"><button class="primary">Save Question</button></div></form></div>`,'Question Bank Creator','MCQ questions are automatically evaluated; subjective questions require manual assessment');$('#qForm').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));let q={id:Date.now(),text:f.text,subject:f.subject,type:f.type,marks:+f.marks,difficulty:f.difficulty,status:'ACTIVE'};if(f.type==='MCQ'){q.options=['A','B','C','D'].map(x=>f[x]);q.correct=f.correct;if(q.options.some(v=>!v))return alert('All four MCQ options are required.')}else q.guidance=f.guidance;data.questions.push(q);audit('QUESTION_CREATED',`${f.type} · ${f.subject}`);save();go('/admin/questions')}}
function questionTypeFields(){let sub=$('#qType').value==='SUBJECTIVE';$('#mcqFields').hidden=sub;$('#subjectiveFields').hidden=!sub}
function exam(){let a=data.applications.find(x=>x.traineeId===1),r=data.rolls.find(x=>x.traineeId===1),cfg=examConfig(),opens=new Date(`${cfg.date}T${cfg.start}:00`),closes=new Date(opens.getTime()+cfg.duration*60000),now=new Date();if(data.result)return shell(`<div class="panel"><h3>Examination completed</h3><p>Your answers are locked and evaluation is complete.</p><button class="primary" onclick="go('/trainee/result')">View Result</button></div>`,'Online Examination');if(!a||a.status!=='APPROVED'||!r)return shell(`<div class="panel"><h3>Not yet eligible</h3><p class="muted">An approved application and a generated roll number are required.</p></div>`,'Online Examination');if(cfg.status!=='SCHEDULED'||now<opens||now>=closes)return shell(`<div class="panel"><h3>Exam access is locked</h3><p><b>${esc(cfg.name)}</b> is scheduled for <b>${opens.toLocaleString()}</b>.</p><p class="muted">The examination becomes accessible only at the administrator-configured start time and closes at ${closes.toLocaleTimeString()}.</p></div>`,'Online Examination','Strict schedule access control');let q=data.questions.filter(x=>(x.type||'MCQ')==='MCQ').slice(0,10),attempt=data.attempt||{answers:{},start:Date.now(),review:{}};data.attempt=attempt;save();let current=0;function draw(){let x=q[current],remaining=Math.max(0,closes-Date.now());shell(`<div class="exam"><div class="exam-top"><b>${esc(cfg.name)}</b><span class="timer" id="timer">Time Remaining: ${new Date(remaining).toISOString().slice(14,19)}</span></div><div class="panel"><div class="muted">Question ${current+1} of ${q.length}</div><div class="question">${esc(x.text)}</div>${x.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${'ABCD'[i]}" ${attempt.answers[x.id]==='ABCD'[i]?'checked':''}> ${'ABCD'[i]}. ${esc(o)}</label>`).join('')}<p class="actions"><button class="secondary" onclick="examMove(-1)" ${current?'':'disabled'}>Previous</button><button class="secondary" onclick="markReview(${x.id})">Mark for Review</button><button class="primary" onclick="examMove(1)">${current===q.length-1?'Save & Review':'Save & Next'}</button></p><div class="palette">${q.map((z,i)=>`<button class="${attempt.answers[z.id]?'answered':''}" onclick="examJump(${i})">${i+1}</button>`).join('')}</div><p><button class="primary" onclick="submitExam()">Submit Examination</button></p></div></div>`,'Online Examination','Access is controlled by the administrator schedule');document.querySelectorAll('[name=answer]').forEach(e=>e.onchange=()=>{attempt.answers[x.id]=e.target.value;save();draw()})}window.examMove=d=>{let chosen=$('[name=answer]:checked');if(chosen)attempt.answers[q[current].id]=chosen.value;current=Math.min(q.length-1,Math.max(0,current+d));save();draw()};window.examJump=i=>{current=i;draw()};window.markReview=id=>{attempt.review[id]=true;save();alert('Question marked for review.')};draw()}
function render(){route=location.hash.slice(1)||'/login';if(route.startsWith('/certificate/verify/'))return verify();if(route==='/register')return selfRegister();if(!session)return login();let fn={'/admin/dashboard':dashboard,'/admin/courses':listCourses,'/admin/batches':batches,'/admin/trainees':trainees,'/admin/verifications':verifications,'/admin/attendance':attendance,'/admin/materials':materials,'/admin/applications':applications,'/admin/exam-schedule':examSchedule,'/admin/questions':questions,'/admin/rolls':rolls,'/admin/results':results,'/admin/certificates':certificates,'/admin/audit':auditLog,'/trainee/dashboard':traineeDashboard,'/trainee/profile':()=>traineeView(1),'/trainee/attendance':()=>shell(`<div class="panel"><h3>Attendance Summary</h3><p>Working Days: 60 · Present: 55 · Absent: 5</p><h2>92%</h2><div class="progress"><i style="width:92%"></i></div></div>`,'My Attendance'),'/trainee/materials':materials,'/trainee/application':application,'/trainee/exam':exam,'/trainee/result':traineeResult,'/trainee/certificate':certificate}[route];if(!fn)return go(session.role==='TRAINEE'?'/trainee/dashboard':'/admin/dashboard');let traineeRoute=route.startsWith('/trainee');if((session.role==='TRAINEE')!==traineeRoute)return go(session.role==='TRAINEE'?'/trainee/dashboard':'/admin/dashboard');fn()}window.addEventListener('hashchange',render);render();
